#!/usr/bin/env bash
# Persist state with retry (2026-11-04, pt13u): run 41811293782 lost its state on a single GitHub 500 at push.
# usage: bash scripts/persist_state.sh "<commit message>" <path>...
# - up to PERSIST_TRIES (5) rounds of: git pull --rebase origin main, then git push; backoff 5, 15, 30, 60 s.
# - rebase conflicts on state/*.json keep THIS run's state (in a rebase that is --theirs);
#   state/archive.json keeps upstream (--ours) and is regenerated by ntfy_archive.py, as before.
# - a conflict outside state/ aborts that round's rebase (never auto-resolved).
# - on final failure writes persist_failed=1 to $GITHUB_OUTPUT and exits 1, so the workflow uploads state/ as an
#   artifact and the ops notice says so.
set -u
msg=${1:?commit message}; shift
case "$msg" in
  *"[skip ci]"*|*"[ci skip]"*|*"[skip actions]"*|*"[actions skip]"*) ;;
  *) msg="$msg [skip ci]" ;;
esac
tries=${PERSIST_TRIES:-5}
read -r -a delays <<<"${PERSIST_DELAYS:-5 15 30 60}"
remote=${PERSIST_REMOTE:-origin}
branch=${PERSIST_BRANCH:-main}

git config user.name "cwally-alerts-bot"
git config user.email "github-actions[bot]@users.noreply.github.com"
git add "$@"
if git diff --staged --quiet; then echo unchanged; exit 0; fi
git commit -q -m "$msg"

in_rebase() { [ -d "$(git rev-parse --git-path rebase-merge)" ] || [ -d "$(git rev-parse --git-path rebase-apply)" ]; }

resolve_rebase() {
  local guard=0 f
  while in_rebase; do
    guard=$((guard + 1))
    if [ "$guard" -gt 50 ]; then git rebase --abort; return 1; fi
    while IFS= read -r f; do
      [ -n "$f" ] || continue
      case "$f" in
        state/archive.json)
          git checkout --ours -- "$f"
          "$(command -v python || command -v python3)" scripts/ntfy_archive.py || echo "persist: archive regenerate failed; keep upstream archive"
          git add -- "$f" ;;
        state/*|trend_monitor/output/*)
          echo "persist: conflict $f -> keep this run's file (--theirs)"
          if git checkout --theirs -- "$f" 2>/dev/null; then git add -- "$f"; else git rm -q --cached -- "$f" 2>/dev/null || git add -A -- "$f"; fi ;;
        *)
          echo "persist: conflict outside state/ and trend output ($f); abort this round"
          git rebase --abort; return 1 ;;
      esac
    done < <(git diff --name-only --diff-filter=U)
    if git diff --cached --quiet; then
      GIT_EDITOR=true git rebase --skip >/dev/null 2>&1 || true
    else
      GIT_EDITOR=true git rebase --continue >/dev/null 2>&1 || true
    fi
  done
  return 0
}

for ((i = 1; i <= tries; i++)); do
  if git pull -q --rebase --autostash "$remote" "$branch" || resolve_rebase; then
    if git push "$remote" "HEAD:$branch"; then
      echo "persist ok (try $i/$tries)"
      exit 0
    fi
  fi
  in_rebase && git rebase --abort
  if [ "$i" -lt "$tries" ]; then
    d=${delays[$((i - 1))]:-${delays[-1]}}
    echo "persist: try $i/$tries failed; retry in ${d}s"
    sleep "$d"
  fi
done
echo "::error::persist state failed after $tries tries; state/ will be uploaded as an artifact"
[ -n "${GITHUB_OUTPUT:-}" ] && echo "persist_failed=1" >> "$GITHUB_OUTPUT"
exit 1
